draw:
var k = p.k, m = p.mass, A = p.amplitude;
var w = Math.sqrt(k / m);
var x = A * Math.cos(w * t);
var v = -A * w * Math.sin(w * t);
var U = 0.5 * k * x * x;
var K = 0.5 * m * v * v;
var E = 0.5 * k * A * A;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";
ctx.textBaseline = "alphabetic";

var wallX = W * 0.06;
var eqX = W * 0.42;
var scale = (W * 0.28) / Math.max(A, 0.01);
var midY = H * 0.28;
var massX = eqX + x * scale;
var half = Math.max(10, W * 0.028);

// ground line
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(wallX, midY + half + 4);
ctx.lineTo(W - 8, midY + half + 4);
ctx.stroke();

// wall
ctx.fillStyle = C.faint;
ctx.fillRect(wallX - 7, midY - half - 12, 7, 2 * half + 16);

// spring
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(wallX, midY);
var span = massX - half - wallX;
for (var i = 1; i <= 14; i++) {
  var sx = wallX + span * i / 14;
  var sy = midY + (i % 2 === 0 ? -9 : 9) * (i === 14 ? 0 : 1);
  ctx.lineTo(sx, sy);
}
ctx.lineTo(massX - half, midY);
ctx.stroke();

// equilibrium marker and turning points
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 5]);
ctx.beginPath();
ctx.moveTo(eqX, midY - half - 18); ctx.lineTo(eqX, midY + half + 4);
ctx.moveTo(eqX - A * scale, midY - half - 10); ctx.lineTo(eqX - A * scale, midY + half + 4);
ctx.moveTo(eqX + A * scale, midY - half - 10); ctx.lineTo(eqX + A * scale, midY + half + 4);
ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("x = 0", eqX, midY - half - 22);
ctx.fillText("-A", eqX - A * scale, midY - half - 14);
ctx.fillText("+A", eqX + A * scale, midY - half - 14);

// mass
ctx.fillStyle = C.figure;
ctx.fillRect(massX - half, midY - half, 2 * half, 2 * half);

// velocity arrow
if (Math.abs(v) > 0.01 * A * w + 1e-6) {
  var dir = v > 0 ? 1 : -1;
  var len = (Math.abs(v) / Math.max(A * w, 1e-6)) * W * 0.11;
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(massX, midY);
  ctx.lineTo(massX + dir * len, midY);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(massX + dir * len, midY);
  ctx.lineTo(massX + dir * (len - 6), midY - 4);
  ctx.lineTo(massX + dir * (len - 6), midY + 4);
  ctx.closePath();
  ctx.fillStyle = C.accent;
  ctx.fill();
  ctx.fillStyle = C.accent;
  ctx.textAlign = "center";
  ctx.fillText("v", massX + dir * len * 0.5, midY - 8);
}

// energy bars
var baseY = H * 0.90;
var topY = H * 0.52;
var full = baseY - topY;
var bw = Math.max(26, W * 0.10);
var gap = W * 0.055;
var x0 = W * 0.16;
var labels = ["U", "K", "U + K"];
var vals = [U, K, U + K];
for (var b = 0; b < 3; b++) {
  var bx = x0 + b * (bw + gap);
  var frac = E > 0 ? vals[b] / E : 0;
  if (frac > 1) frac = 1;
  ctx.strokeStyle = C.rule;
  ctx.lineWidth = 1;
  ctx.strokeRect(bx, topY, bw, full);
  ctx.fillStyle = b === 2 ? C.figure : C.accent;
  ctx.fillRect(bx, baseY - full * frac, bw, full * frac);
  ctx.fillStyle = C.ink;
  ctx.textAlign = "center";
  ctx.fillText(labels[b], bx + bw / 2, baseY + 14);
  ctx.fillText(vals[b].toFixed(2) + " J", bx + bw / 2, topY - 6);
}

// the ceiling line: total energy
ctx.strokeStyle = C.faint;
ctx.setLineDash([2, 4]);
ctx.beginPath();
ctx.moveTo(x0 - 8, topY); ctx.lineTo(x0 + 3 * bw + 2 * gap + 8, topY);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("E = kA^2 / 2 = " + E.toFixed(2) + " J", x0 + 3 * bw + 2 * gap + 14, topY + 4);

out.note = "x = " + x.toFixed(3) + " m, v = " + v.toFixed(2) + " m/s, U = " + U.toFixed(3) +
  " J, K = " + K.toFixed(3) + " J, sum = " + (U + K).toFixed(3) + " J";

var k = p.k, A = p.amplitude, f = p.frac;
var E = 0.5 * k * A * A;
var x = f * A;
var U = 0.5 * k * x * x;
var K = E - U;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "alphabetic";

var padL = W * 0.12, padR = W * 0.06;
var x0 = padL, x1 = W - padR;
var cx = (x0 + x1) / 2;
var baseY = H * 0.86, topY = H * 0.14;
var xs = (x1 - x0) / 2 / (1.25 * A);
var ys = (baseY - topY) / (0.5 * k * (1.25 * A) * (1.25 * A));

// axes
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(x0, baseY); ctx.lineTo(x1, baseY);
ctx.moveTo(cx, baseY + 6); ctx.lineTo(cx, topY - 6);
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.textAlign = "right";
ctx.fillText("energy", cx - 8, topY + 2);
ctx.textAlign = "left";
ctx.fillText("x", x1 - 10, baseY + 16);

// the parabola U = kx^2/2
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 120; i++) {
  var xx = -1.25 * A + (2.5 * A) * i / 120;
  var px = cx + xx * xs;
  var py = baseY - 0.5 * k * xx * xx * ys;
  if (py < topY) py = topY;
  i === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
}
ctx.stroke();

// total energy line
var eY = baseY - E * ys;
ctx.strokeStyle = C.accent;
ctx.setLineDash([5, 4]);
ctx.beginPath();
ctx.moveTo(x0, eY); ctx.lineTo(x1, eY);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("E = " + E.toFixed(2) + " J", x0 + 2, eY - 6);

// turning points
ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("-A", cx - A * xs, baseY + 16);
ctx.fillText("+A", cx + A * xs, baseY + 16);
ctx.strokeStyle = C.rule;
ctx.setLineDash([2, 4]);
ctx.beginPath();
ctx.moveTo(cx - A * xs, baseY); ctx.lineTo(cx - A * xs, eY);
ctx.moveTo(cx + A * xs, baseY); ctx.lineTo(cx + A * xs, eY);
ctx.stroke();
ctx.setLineDash([]);

// the split at x
var px2 = cx + x * xs;
var uY = baseY - U * ys;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 5;
ctx.beginPath();
ctx.moveTo(px2, baseY); ctx.lineTo(px2, uY);
ctx.stroke();
ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(px2, uY); ctx.lineTo(px2, eY);
ctx.stroke();
ctx.lineWidth = 1;

ctx.fillStyle = C.figure;
ctx.textAlign = px2 > cx ? "left" : "right";
var off = px2 > cx ? 8 : -8;
ctx.fillText("U = " + U.toFixed(2) + " J", px2 + off, (baseY + uY) / 2 + 4);
ctx.fillStyle = C.accent;
ctx.fillText("K = " + K.toFixed(2) + " J", px2 + off, (uY + eY) / 2 + 4);
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("x = " + x.toFixed(3) + " m", px2, baseY + 30);

out.note = "at x = " + f.toFixed(2) + "A the kinetic share is " +
  (1 - f * f).toFixed(3) + " of E; K = U when x = 0.707A";

var k = p.k, m = p.mass, mu = p.mu, A0 = p.A0;
var g = 9.8;
var w = Math.sqrt(k / m);
var T = 2 * Math.PI / w;
var x0 = mu * m * g / k;

// position at time tt, walking half-cycle by half-cycle
var amp = function (n) { return A0 - 2 * n * x0; };
var stopN = 0;
while (amp(stopN) > 2 * x0 && stopN < 400) { stopN++; }

// resting place: where it stalls, on the far side of the last half-cycle
var restX;
if (stopN === 0) {
  restX = A0;
} else {
  var sPrev = (stopN - 1) % 2 === 0 ? 1 : -1;
  restX = -sPrev * amp(stopN);
}

var xAt = function (tt) {
  var n = Math.floor(tt / (T / 2));
  if (n >= stopN) { return restX; }
  var s = n % 2 === 0 ? 1 : -1;
  var a = amp(n);
  var tau = tt - n * (T / 2);
  return s * (x0 + (a - x0) * Math.cos(w * tau));
};

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "alphabetic";

var x = xAt(t);
var n = Math.floor(t / (T / 2));
if (n > stopN) n = stopN;
var Enow = 0.5 * k * (n >= stopN ? restX * restX : amp(n) * amp(n));
var E0 = 0.5 * k * A0 * A0;

var eqX = W * 0.5;
var midY = H * 0.26;
var scale = (W * 0.40) / Math.max(A0, 0.01);
var half = Math.max(9, W * 0.022);
var massX = eqX + x * scale;

// rough ground
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(W * 0.05, midY + half + 4); ctx.lineTo(W * 0.95, midY + half + 4);
ctx.stroke();
for (var i = 0; i < 24; i++) {
  var hx = W * 0.05 + (W * 0.90) * i / 23;
  ctx.beginPath();
  ctx.moveTo(hx, midY + half + 4); ctx.lineTo(hx - 5, midY + half + 10);
  ctx.stroke();
}

// dead band
ctx.fillStyle = C.faint;
ctx.globalAlpha = 0.25;
ctx.fillRect(eqX - x0 * scale, midY - half - 14, 2 * x0 * scale, 2 * half + 18);
ctx.globalAlpha = 1;
ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("stuck band, width 2mu*m*g/k", eqX, midY - half - 20);

// block
ctx.fillStyle = C.figure;
ctx.fillRect(massX - half, midY - half, 2 * half, 2 * half);

// friction arrow, opposing motion
var vsign = 0;
var dt = 0.004;
vsign = xAt(t + dt) - xAt(t - dt) > 0 ? 1 : -1;
if (n < stopN) {
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 2;
  var fl = W * 0.07;
  ctx.beginPath();
  ctx.moveTo(massX, midY + half + 12);
  ctx.lineTo(massX - vsign * fl, midY + half + 12);
  ctx.stroke();
  ctx.fillStyle = C.accent;
  ctx.textAlign = "center";
  ctx.fillText("friction", massX - vsign * fl * 0.5, midY + half + 26);
}

// amplitude staircase: x(t) trace with straight envelope
var gTop = H * 0.50, gBot = H * 0.95;
var gMid = (gTop + gBot) / 2;
var gy = (gBot - gTop) / 2 / Math.max(A0, 0.01);
var tSpan = Math.max(stopN + 1, 2) * (T / 2);
var gx0 = W * 0.08, gx1 = W * 0.92;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(gx0, gMid); ctx.lineTo(gx1, gMid);
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("x versus time", gx0, gTop + 10);

// envelope
ctx.strokeStyle = C.faint;
ctx.setLineDash([4, 4]);
ctx.beginPath();
ctx.moveTo(gx0, gMid - A0 * gy);
ctx.lineTo(gx0 + (gx1 - gx0) * (stopN * (T / 2)) / tSpan, gMid - Math.max(amp(stopN), 0) * gy);
ctx.moveTo(gx0, gMid + A0 * gy);
ctx.lineTo(gx0 + (gx1 - gx0) * (stopN * (T / 2)) / tSpan, gMid + Math.max(amp(stopN), 0) * gy);
ctx.stroke();
ctx.setLineDash([]);

ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5;
ctx.beginPath();
var drawnTo = Math.min(t, tSpan);
for (var j = 0; j <= 400; j++) {
  var tt = drawnTo * j / 400;
  var gpx = gx0 + (gx1 - gx0) * tt / tSpan;
  var gpy = gMid - xAt(tt) * gy;
  j === 0 ? ctx.moveTo(gpx, gpy) : ctx.lineTo(gpx, gpy);
}
ctx.stroke();
ctx.lineWidth = 1;

out.note = "half-cycles done " + n + " of " + stopN + " (complete cycles " + Math.floor(n / 2) +
  " of " + Math.floor(stopN / 2) + "), amplitude now " +
  (n >= stopN ? Math.abs(restX) : amp(n)).toFixed(4) + " m, energy left " +
  Enow.toFixed(4) + " J of " + E0.toFixed(4) + " J, total path so far " +
  ((E0 - Enow) / (mu * m * g)).toFixed(3) + " m";
